const $ = id => document.getElementById(id);
const state = { manifest: null, scenarios: new Map(), selected: null, section: "basics" };
const key = "tss-scenario-editor-draft-v2";
const VERSION = 2;
const LEGACY_VERSION = 1;
const DEFAULT_FACILITY_ID = "TSS_MAIN";
const DEFAULT_CATALOG_ID = "TSS_MAIN_CATALOG";
const required = ["inventory","cableInventory","cableTypeRequirements","permanentConnections","cableSchedule","namingRows","racks","expectedRackPlacements","expectedEndpointPlacements","networkScenario","binderReference"];
const networkFields = { networkCircuitId: "circuitId", networkSsid: "ssid", networkWifiPassphrase: "wifiPassphrase", networkWirelessChannel: "wirelessChannel", networkApAdminPassword: "apAdminPassword", networkEnableSecret: "enableSecret", networkConsolePassword: "consolePassword", networkVtyPassword: "vtyPassword" };
const authoredFields = Object.values(networkFields).filter(field => field !== "wirelessChannel");
const groups = {
  network: ["networkScenario"],
  facility: ["inventory","cableInventory","defaultPlayerCableType","cableTypeRequirements","permanentConnections","cableSchedule","namingRows","racks","expectedRackPlacements","expectedEndpointPlacements"],
  binder: ["binderReference"]
};
const help = {
  networkScenario: "Network values, device roles, configuration expectations, and evidence for the student lab.",
  inventory: "Equipment IDs must match Unity’s equipment catalog. Quantity controls how many items are available.",
  cableInventory: "Cable IDs must match Unity’s cable catalog. Quantity controls available loose cable stock.",
  defaultPlayerCableType: "Cable type offered by default in the student cable placement workflow.",
  cableTypeRequirements: "Required cable class between two stable endpoint IDs.",
  permanentConnections: "Fixed infrastructure links, such as wallports connected to patch-panel ports.",
  cableSchedule: "Binder-facing cable run instructions. These names and ports are shown to students.",
  namingRows: "Device names, rack positions, and rationale shown in the naming reference.",
  racks: "Rack U ranges and reserved positions supported by the selected Unity facility.",
  expectedRackPlacements: "Expected equipment placements used by the training phase checks.",
  expectedEndpointPlacements: "Expected endpoint placements used by the training phase checks.",
  binderReference: "Text and tables shown in the student binder. Use supported instructor-authored tokens where appropriate.",
  dhcpNetworkNames: "Network names that should receive an address through DHCP during the training run.",
  endpointAliases: "Student-facing endpoint names. These must align with the facility and expected endpoint placements.",
  roleBindings: "Maps training roles such as AN-1 and CN-1 to the stable facility device that performs that role.",
  requiredPorts: "Defines the device interface each named endpoint is expected to use. These relationships drive connection and configuration checks.",
  evidenceRequirements: "Commands and evidence the student must provide to demonstrate the network is working.",
  reservedUPositions: "Rack units that remain unavailable for installation, such as a fixed patch panel position.",
  rows: "The labeled values students see in this binder section. Tokens are resolved when a scenario runs.",
  namingAndRacks: "Explains equipment naming and rack placement conventions for this scenario.",
  vlans: "Explains the VLAN design, trunk behavior, and unused-port expectations.",
  ipPlan: "Provides the student-facing addressing guidance used during configuration.",
  circuitLetter: "Provides the circuit reference and WAN handoff instructions.",
  wireless: "Provides the access point configuration values and wireless acceptance criteria.",
  credentials: "Provides the device access settings and login-banner guidance used by the lab."
};
const binderNames = { namingAndRacks: "Naming & Racks", vlans: "VLANs", ipPlan: "IP Plan", cableSchedule: "Cable Schedule", circuitLetter: "Circuit Letter", wireless: "Wireless", credentials: "Credentials" };
const setStatus = text => { $("status").textContent = text; };
const filename = id => `${String(id || "scenario").toLowerCase().replace(/[^a-z0-9_-]+/g,"-")}.json`;
const download = (name, value) => { const a=document.createElement("a"); a.href=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)+"\n"],{type:"application/json"})); a.download=name; a.click(); setTimeout(()=>URL.revokeObjectURL(a.href),1000); };
function selected() { try { return JSON.parse($("json").value); } catch { return null; } }
function entryFor(id = state.selected) { return (state.manifest?.scenarios || []).find(entry => entry.scenarioId === id); }
function normalizeScenario(data) { if(data && data.schemaVersion===LEGACY_VERSION) { data.schemaVersion=VERSION; data.facilityId ||= DEFAULT_FACILITY_ID; data.catalogId ||= DEFAULT_CATALOG_ID; data.sceneName ||= "TSS"; } return data; }
function normalizeManifest(manifest) { if(!manifest) return manifest; if(manifest.schemaVersion===LEGACY_VERSION) manifest.schemaVersion=VERSION; (manifest.scenarios||[]).forEach(entry=>{ if(entry && !entry.facilityId) entry.facilityId=DEFAULT_FACILITY_ID; if(entry && !entry.catalogId) entry.catalogId=DEFAULT_CATALOG_ID; if(entry && !entry.sceneName) entry.sceneName="TSS"; }); return manifest; }
function manifestErrors(manifest) {
  const errors=[];
  if(!manifest || manifest.format!=="tss-scenario-manifest" || manifest.schemaVersion!==VERSION) errors.push("Manifest must use tss-scenario-manifest schema version 2.");
  const ids=new Set(), files=new Set(), rows=manifest?.scenarios;
  if(!Array.isArray(rows)||!rows.length) errors.push("Manifest must contain at least one scenario.");
  (rows||[]).forEach((entry,i)=>{const id=String(entry?.scenarioId||""),file=String(entry?.jsonFile||"");if(!id.trim()||ids.has(id.toLowerCase()))errors.push(`Manifest entry ${i+1} has a missing or duplicate scenarioId.`);ids.add(id.toLowerCase());if(!file.trim()||files.has(file.toLowerCase()))errors.push(`Manifest entry ${i+1} has a missing or duplicate jsonFile.`);files.add(file.toLowerCase());["displayName","facilityId","catalogId","sceneName"].forEach(k=>!String(entry?.[k]||"").trim()&&errors.push(`Manifest entry ${i+1} is missing ${k}.`));if(file&&!/^[A-Za-z0-9_-]+\.json$/.test(file))errors.push(`Manifest entry ${i+1} has an invalid local jsonFile.`);});
  return errors;
}
function tokenValues(network = {}, scenarioId = "") { return { "{ScenarioId}":scenarioId, "{CircuitId}":network.circuitId, "{Ssid}":network.ssid, "{WifiPassphrase}":network.wifiPassphrase, "{WirelessChannel}":network.wirelessChannel, "{ApAdminPassword}":network.apAdminPassword, "{EnableSecret}":network.enableSecret, "{ConsolePassword}":network.consolePassword, "{VtyPassword}":network.vtyPassword, "{Motd}":network.motd }; }
function resolveTokens(value, network, scenarioId) { let resolved=String(value ?? ""); Object.entries(tokenValues(network,scenarioId)).forEach(([token,replacement]) => resolved=resolved.replaceAll(token,String(replacement ?? ""))); return resolved; }
function errorsFor(data, manifest) {
  const errors=manifestErrors(manifest); if(!data||typeof data!=="object"||Array.isArray(data))return errors.concat(["Scenario JSON must be an object."]);
  normalizeScenario(data);
  if(data.format!=="tss-scenario"||data.schemaVersion!==VERSION)errors.push("Scenario must use tss-scenario schema version 2 (version 1 is migrated automatically).");
  ["scenarioId","displayName","facilityId","catalogId","sceneName"].forEach(k=>!String(data[k]||"").trim()&&errors.push(`${k} is required.`));
  if(data.sceneName!=="TSS")errors.push("Only the TSS scene is supported.");
  required.forEach(k=>data[k]===undefined&&errors.push(`${k} is required.`));
  const network=data.networkScenario||{}; authoredFields.forEach(field=>!String(network[field]||"").trim()&&errors.push(`networkScenario.${field} is required.`));
  if(![1,6,11].includes(Number(network.wirelessChannel)))errors.push("networkScenario.wirelessChannel must be 1, 6, or 11.");
  const unique=(rows,field,label)=>{const seen=new Set;(Array.isArray(rows)?rows:[]).forEach((r,i)=>{const v=String(r?.[field]??"");if(!v.trim()||v!==v.trim()||seen.has(v.toLowerCase()))errors.push(`${label} ${i+1} has a missing, padded, or duplicate ${field}.`);seen.add(v.toLowerCase());});};
  unique(data.inventory,"equipmentId","Inventory");unique(data.cableInventory,"cableId","Cable inventory");unique(data.permanentConnections,"connectionId","Permanent connection");unique(data.cableTypeRequirements,"requirementId","Cable requirement");
  ["inventory","cableInventory"].forEach(k=>(Array.isArray(data[k])?data[k]:[]).forEach((r,i)=>{if(!Number.isInteger(r?.quantity)||r.quantity<0)errors.push(`${k} row ${i+1} has an invalid quantity.`);}));
  (Array.isArray(data.racks)?data.racks:[]).forEach(r=>{if(!r?.rackId||r.lowestU<1||r.highestU>40||r.lowestU>r.highestU||r.firstInstallableU<r.lowestU||r.lastInstallableU>r.highestU||r.firstInstallableU>r.lastInstallableU)errors.push(`Invalid rack range: ${r?.rackId||"missing rack"}.`);});
  if(manifest){const entry=(manifest.scenarios||[]).find(x=>x.scenarioId===data.scenarioId);if(!entry)errors.push("Scenario ID is not in the manifest.");else if(entry.displayName!==data.displayName||entry.facilityId!==data.facilityId||entry.catalogId!==data.catalogId||entry.sceneName!==data.sceneName)errors.push("Scenario identity does not match its manifest entry.");}
  return errors;
}
function renderValidation(){const data=selected(),errors=errorsFor(data,state.manifest),box=$("errors");box.replaceChildren();if(!errors.length){const li=document.createElement("li");li.className="ok";li.textContent="Ready for Unity validation.";box.append(li);}else errors.forEach(e=>{const li=document.createElement("li");li.textContent=e;box.append(li);});return errors;}
function renderBinder(){
  const root=$("binder"),data=selected(),network=data?.networkScenario,binder=data?.binderReference;root.replaceChildren();
  if(!binder){root.textContent="No binder content available.";return;}
  Object.entries(binder).forEach(([key,section])=>{if(!section)return;const n=$("binderTemplate").content.cloneNode(true),article=n.querySelector("article");article.querySelector("h4").textContent=section.sectionTitle||binderNames[key]||"Untitled section";article.querySelector("strong").textContent=resolveTokens(section.scenarioHeading,network,data?.scenarioId);article.querySelector("p").textContent=Object.entries(section).filter(([name,value])=>!['sectionTitle','scenarioHeading','rows'].includes(name)&&typeof value==="string"&&value).map(([,value])=>resolveTokens(value,network,data?.scenarioId)).join("\n\n");const rows=article.querySelector("dl");(Array.isArray(section.rows)?section.rows:[]).forEach(row=>{const label=document.createElement("dt"),value=document.createElement("dd");label.textContent=row.label||"";value.textContent=resolveTokens(row.value,network,data?.scenarioId);rows.append(label,value);});root.append(n);});
}
function prettyName(value){return String(value).replace(/([A-Z])([A-Z][a-z])/g,"$1 $2").replace(/([a-z0-9])([A-Z])/g,"$1 $2").replace(/[_-]+/g," ").replace(/^./,x=>x.toUpperCase());}
function pathValue(root,path){return path.reduce((value,key)=>value?.[key],root);}
function longText(key,value){return typeof value==="string"&&(value.length>110||/motd|paragraph|intro|ending|rationale|description|heading|note|address/i.test(key));}
function makeDefaultArrayItem(path){const name=String(path.at(-1)||"");const templates={inventory:{equipmentId:"",quantity:0},cableInventory:{cableId:"",quantity:0},cableTypeRequirements:{requirementId:"",endpointAId:"",endpointBId:"",requiredCableType:0},permanentConnections:{connectionId:"",cableId:"",cableType:0,patchPanelEndpointId:"",wallportEndpointId:"",requiresPunchDownTermination:false,endpointATerminationModuleId:"",endpointBTerminationModuleId:""},cableSchedule:{fromEndpoint:"",fromPort:"",toEndpoint:"",toPort:"",cableType:"Straight"},namingRows:{rackId:"",slot:"",device:"",assignedName:"",rationale:""},racks:{rackId:"",lowestU:1,highestU:40,firstInstallableU:1,lastInstallableU:40,reservedUPositions:[]},reservedUPositions:1,expectedRackPlacements:{phaseLabel:"",rackId:"",startingU:1,endingU:1,category:0,requiredName:""},expectedEndpointPlacements:{phaseLabel:"",stationId:"",category:0,requiredName:""},rows:{label:"",value:""},roleBindings:{role:"",deviceKey:"",category:0,displayName:""},requiredPorts:{deviceRole:"",interfaceName:"",endpointId:""},evidenceRequirements:{evidenceId:"",command:"",description:""},dhcpNetworkNames:"",endpointAliases:""};return structuredClone(templates[name]??{});}
function blankLike(value){if(Array.isArray(value))return[];if(value&&typeof value==="object")return Object.fromEntries(Object.entries(value).map(([k,v])=>[k,blankLike(v)]));if(typeof value==="number")return 0;if(typeof value==="boolean")return false;return "";}
function card(title,description){const section=document.createElement("section");section.className="data-card";const head=document.createElement("div");head.className="data-card-heading";const h=document.createElement("h3");h.textContent=title;head.append(h);if(description){const p=document.createElement("p");p.textContent=description;head.append(p);}section.append(head);return section;}
function singularName(name){return name.endsWith("ies")?`${name.slice(0,-3)}y`:name.endsWith("s")?name.slice(0,-1):name;}
function rowSummary(item,index){const keys=["assignedName","requiredName","connectionId","requirementId","equipmentId","cableId","evidenceId","deviceRole","phaseLabel","role","label","rackId","fromEndpoint"];const first=keys.find(key=>item?.[key]);let summary=first?String(item[first]):`Item ${index+1}`;if(item?.quantity!==undefined)summary+=` · Qty ${item.quantity}`;if(item?.fromEndpoint)summary+=` ${item.fromPort||""} → ${item.toEndpoint||""} ${item.toPort||""}`;else if(item?.endpointAId)summary+=` · ${item.endpointAId} → ${item.endpointBId||""}`;else if(item?.patchPanelEndpointId)summary+=` · ${item.patchPanelEndpointId} → ${item.wallportEndpointId||""}`;else if(item?.stationId)summary+=` · ${item.stationId}`;else if(item?.rackId&&item?.startingU)summary+=` · U${item.startingU}–U${item.endingU}`;else if(item?.value!==undefined&&item?.label)summary+=`: ${item.value}`;return summary.trim();}
function fieldControl(name,value,path){
  const label=document.createElement("label");label.className="data-field";const title=document.createElement("span");title.className="data-field-label";title.textContent=prettyName(name);label.append(title);if(["category","cableType","requiredCableType","defaultPlayerCableType"].includes(name)){const hint=document.createElement("span");hint.className="hint";hint.textContent="Numeric Unity catalog value; preserve the code used by a known-good scenario.";label.append(hint);}
  const type=typeof value, input=type==="boolean"?document.createElement("input"):longText(name,value)?document.createElement("textarea"):document.createElement("input");
  input.dataset.path=JSON.stringify(path);input.dataset.valueType=type;input.setAttribute("aria-label",prettyName(name));
  if(type==="boolean"){input.type="checkbox";input.checked=value;input.className="boolean-field";}
  else {input.value=value??"";if(type==="number"){input.type="number";input.step="any";}if(name==="wirelessChannel"){input.type="number";input.min="1";input.max="11";input.step="1";}}
  label.append(input);return label;
}
function renderObjectFields(object,path,container,depth=0){
  if(!object||typeof object!=="object")return;
  if(Array.isArray(object)){const list=document.createElement("div");list.className="repeat-list";object.forEach((item,index)=>{const row=document.createElement("div");row.className="repeat-row";const content=document.createElement("div");content.className="repeat-row-content";if(item&&typeof item==="object"){const details=document.createElement("details");details.className="repeat-details";const summary=document.createElement("summary");summary.textContent=rowSummary(item,index);details.append(summary);const fields=document.createElement("div");fields.className="repeat-fields";renderObjectFields(item,[...path,index],fields,depth+1);details.append(fields);content.append(details);}else content.append(fieldControl(String(index+1),item,[...path,index]));const remove=document.createElement("button");remove.type="button";remove.className="remove-row";remove.textContent="Remove";remove.dataset.action="remove";remove.dataset.path=JSON.stringify(path);remove.dataset.index=index;row.append(content,remove);list.append(row);});const add=document.createElement("button");add.type="button";add.className="add-row";add.textContent=`+ Add ${prettyName(singularName(String(path.at(-1)||"item")))}`;add.dataset.action="add";add.dataset.path=JSON.stringify(path);list.append(add);container.append(list);return;}
  const grid=document.createElement("div");grid.className=`data-fields depth-${Math.min(depth,2)}`;
  Object.entries(object).forEach(([name,value])=>{const valuePath=[...path,name];if(value&&typeof value==="object"){const nested=card(prettyName(name),help[name]||"");renderObjectFields(value,valuePath,nested,depth+1);grid.append(nested);}else grid.append(fieldControl(name,value,valuePath));});container.append(grid);
}
function renderStructuredForms(){const data=selected();if(!data)return;
  for(const [group,keys] of Object.entries(groups)){const root=$(group+"Fields");root.replaceChildren();keys.forEach(name=>{if(data[name]===undefined)return;const section=card(group==="binder"?"Binder sections":prettyName(name),help[name]||"");if(data[name]&&typeof data[name]==="object")renderObjectFields(data[name],[name],section);else section.append(fieldControl(name,data[name],[name]));root.append(section);});}
}
function renderBasic(data=selected()) {if(!data)return;$("basicScenarioId").value=data.scenarioId||"";$("basicDisplayName").value=data.displayName||"";$("basicDescription").value=entryFor()?.description||"";$("basicFacilityId").value=data.facilityId||DEFAULT_FACILITY_ID;$("basicCatalogId").value=data.catalogId||DEFAULT_CATALOG_ID;$("basicSceneName").value=data.sceneName||"TSS";}
function syncJson(){const data=selected();if(!data){setStatus("JSON is incomplete or invalid. Guided values remain at the last valid version.");return false;}normalizeScenario(data);const oldId=state.selected,entry=entryFor(oldId),newId=String(data.scenarioId||"");if(newId!==oldId&&(!/^[A-Za-z0-9_-]+$/.test(newId)||state.scenarios.has(newId))){setStatus("Scenario ID must be unique and use only letters, numbers, hyphens, or underscores.");return false;}if(entry){if(newId!==oldId){entry.scenarioId=newId;entry.jsonFile=filename(newId);state.scenarios.delete(oldId);state.selected=newId;}["displayName","facilityId","catalogId","sceneName"].forEach(field=>entry[field]=data[field]);const option=$("scenarioSelect").selectedOptions[0];if(option){option.value=newId;option.textContent=data.displayName||"Untitled scenario";$("scenarioSelect").value=newId;}}state.scenarios.set(state.selected,data);localStorage.setItem(key,JSON.stringify({manifest:state.manifest,scenarios:[...state.scenarios.entries()],selected:state.selected}));renderBasic(data);renderStructuredForms();renderValidation();renderBinder();setStatus("Valid JSON updated the scenario draft.");return true;}
function save(){const data=selected();if(!data)return;state.scenarios.set(state.selected,data);localStorage.setItem(key,JSON.stringify({manifest:state.manifest,scenarios:[...state.scenarios.entries()],selected:state.selected}));renderValidation();renderBinder();}
function selectScenario(id){state.selected=id;const data=state.scenarios.get(id);if(!data)return;$("emptyState").hidden=true;$("workspace").hidden=false;$("json").value=JSON.stringify(data,null,2);$("json").disabled=false;$("validate").disabled=false;$("downloadScenario").disabled=false;$("downloadManifest").disabled=false;renderBasic(data);renderStructuredForms();renderValidation();renderBinder();}
function populate(selectedId=state.selected){const select=$("scenarioSelect");select.replaceChildren();(state.manifest?.scenarios||[]).forEach(e=>{if(!state.scenarios.has(e.scenarioId))return;select.add(new Option(e.displayName,e.scenarioId));});select.disabled=!select.options.length;if(select.options.length)selectScenario(selectedId&&state.scenarios.has(selectedId)?selectedId:select.value);setStatus(`${state.scenarios.size} scenario${state.scenarios.size===1?"":"s"} loaded.`);}
function writeBasicField(field,value){const data=selected(),entry=entryFor();if(!data||!entry)return;data[field]=value;entry[field]=value;$("json").value=JSON.stringify(data,null,2);if(field==="displayName"&&$("scenarioSelect").selectedOptions[0])$("scenarioSelect").selectedOptions[0].textContent=value||"Untitled scenario";save();}
function renameScenario(){const data=selected(),oldId=state.selected,entry=entryFor(),newId=$("basicScenarioId").value.trim();if(!data||!entry||newId===oldId)return;if(!/^[A-Za-z0-9_-]+$/.test(newId)||state.scenarios.has(newId)){setStatus("Scenario ID must be unique and use only letters, numbers, hyphens, or underscores.");renderBasic(data);return;}data.scenarioId=newId;entry.scenarioId=newId;entry.jsonFile=filename(newId);state.scenarios.delete(oldId);state.scenarios.set(newId,data);state.selected=newId;$("json").value=JSON.stringify(data,null,2);populate(newId);save();}
function activateSection(name,focus=false){state.section=name;document.querySelectorAll(".nav-tab").forEach(tab=>{const active=tab.dataset.section===name;tab.classList.toggle("active",active);tab.setAttribute("aria-selected",String(active));tab.tabIndex=active?0:-1;});document.querySelectorAll(".section-panel").forEach(panel=>panel.hidden=panel.id!==`panel-${name}`);if(focus)document.querySelector(`#tab-${name}`)?.focus();}
function updateFromGuided(path,input){const data=selected();if(!data)return;let value=input.type==="checkbox"?input.checked:input.value;if(input.dataset.valueType==="number")value=input.value===""?0:Number(input.value);const parent=pathValue(data,path.slice(0,-1));if(parent==null)return;parent[path.at(-1)]=value;$("json").value=JSON.stringify(data,null,2);save();}
function handleRepeatAction(button){const path=JSON.parse(button.dataset.path),data=selected(),array=pathValue(data,path);if(!Array.isArray(array))return;if(button.dataset.action==="remove")array.splice(Number(button.dataset.index),1);else {const prototype=array.at(-1);array.push(prototype===undefined?makeDefaultArrayItem(path):blankLike(prototype));}$("json").value=JSON.stringify(data,null,2);save();renderStructuredForms();}
async function loadWorkspace(){const root="../../../Assets/StreamingAssets/Scenarios/";const manifest=normalizeManifest(await fetch(root+"manifest.json").then(r=>{if(!r.ok)throw new Error(`manifest request failed (${r.status})`);return r.json();}));const scenarios=await Promise.all(manifest.scenarios.map(async e=>[e.scenarioId,normalizeScenario(await fetch(root+e.jsonFile).then(r=>{if(!r.ok)throw new Error(`${e.jsonFile} request failed (${r.status})`);return r.json();}))]));state.manifest=manifest;state.scenarios=new Map(scenarios);activateSection("basics");populate();save();}
$("loadWorkspace").onclick=()=>loadWorkspace().catch(e=>setStatus(`Could not load shipped samples: ${e.message}`));
$("importFiles").onchange=async e=>{try{const files=await Promise.all([...e.target.files].map(async f=>[f.name,JSON.parse(await f.text())]));const manifest=normalizeManifest(files.map(x=>x[1]).find(x=>x?.format==="tss-scenario-manifest"));if(!manifest)throw new Error("Import must include manifest.json.");state.manifest=manifest;state.scenarios=new Map(files.map(x=>x[1]).filter(x=>x?.format==="tss-scenario").map(x=>[x.scenarioId,normalizeScenario(x)]));activateSection("basics");populate();save();}catch(error){setStatus(`Could not import package: ${error.message}`);}e.target.value="";};
$("scenarioSelect").onchange=e=>selectScenario(e.target.value);
document.querySelectorAll(".nav-tab").forEach(tab=>{tab.onclick=()=>activateSection(tab.dataset.section);tab.onkeydown=e=>{if(!["ArrowRight","ArrowLeft","Home","End"].includes(e.key))return;e.preventDefault();const tabs=[...document.querySelectorAll(".nav-tab")],index=tabs.indexOf(tab),next=e.key==="Home"?0:e.key==="End"?tabs.length-1:(index+(e.key==="ArrowRight"?1:-1)+tabs.length)%tabs.length;activateSection(tabs[next].dataset.section,true);};});
$("basicScenarioId").onchange=renameScenario;$("basicDisplayName").oninput=e=>writeBasicField("displayName",e.target.value);$("basicFacilityId").oninput=e=>writeBasicField("facilityId",e.target.value);$("basicCatalogId").oninput=e=>writeBasicField("catalogId",e.target.value);$("basicDescription").oninput=e=>{const entry=entryFor();if(entry){entry.description=e.target.value;save();}};
for(const id of ["networkFields","facilityFields","binderFields"]){$(id).addEventListener("input",e=>{const input=e.target.closest("[data-path]");if(input)updateFromGuided(JSON.parse(input.dataset.path),input);});$(id).addEventListener("click",e=>{const button=e.target.closest("[data-action]");if(button)handleRepeatAction(button);});}
$("json").oninput=()=>{if(syncJson())setStatus("Advanced JSON and guided sections are synchronized.");};
$("validate").onclick=()=>{const errors=renderValidation();setStatus(errors.length?`${errors.length} issue${errors.length===1?"":"s"} found.`:"Browser validation passed; run Unity validation before release.");};
$("downloadScenario").onclick=()=>{const data=selected(),entry=entryFor();if(data)download(entry?.jsonFile||filename(data.scenarioId),data);};$("downloadManifest").onclick=()=>state.manifest&&download("manifest.json",state.manifest);$("clearDraft").onclick=()=>{localStorage.removeItem(key);setStatus("Saved browser draft cleared.");};
try{const draft=JSON.parse(localStorage.getItem(key));if(draft?.manifest){state.manifest=normalizeManifest(draft.manifest);state.scenarios=new Map(draft.scenarios.map(([id,data])=>[id,normalizeScenario(data)]));state.selected=draft.selected;populate(draft.selected);activateSection("basics");setStatus("Recovered local draft.");}}catch{}
